pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // sep is guaranteed non-empty by the problem statement.
    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                return vec![s];
            }
            if s.is_empty() {
                return vec![String::new()];
            }

            let parts: Vec<&str> = s.rsplitn((maxsplit as usize) + 1, &sep).collect();
            // rsplitn yields from the right; reverse to return in left-to-right order.
            parts.into_iter().rev().map(str::to_string).collect()
        })
        .collect()
}